urlset:


    {{ site_url }}/
    {{ lastmod|date:"Y-m-d" }}
    daily
    1.0



{% for category in categories %}

    {{ site_url }}{{ category.get_absolute_url }}
    {{ lastmod|date:"Y-m-d" }}
    weekly
    0.8

{% endfor %}


{% for brand in brands %}

    {{ site_url }}{{ brand.get_absolute_url }}
    {{ lastmod|date:"Y-m-d" }}
    weekly
    0.8

{% endfor %}


{% for product in products %}

    {{ site_url }}{{ product.get_absolute_url }}
    {% if product.updated_at %}{{ product.updated_at|date:"Y-m-d" }}{% else %}{{ lastmod|date:"Y-m-d" }}{% endif %}
    weekly
    0.9

{% endfor %}
